function alienOrder(words) {
  const next = new Map();                     // letter -> letters that come after it
  const indegree = new Map();                 // letter -> how many letters must come first
  for (const word of words) {
    for (const ch of word) {
      if (!next.has(ch)) {
        next.set(ch, new Set());
        indegree.set(ch, 0);
      }
    }
  }
  for (let i = 0; i + 1 < words.length; i++) {
    const a = words[i], b = words[i + 1];
    if (a.length > b.length && a.startsWith(b)) return "";   // "abc" before "ab": impossible
    for (let j = 0; j < Math.min(a.length, b.length); j++) {
      if (a[j] !== b[j]) {                    // the first difference is the only clue
        if (!next.get(a[j]).has(b[j])) {
          next.get(a[j]).add(b[j]);           // a[j] comes before b[j]
          indegree.set(b[j], indegree.get(b[j]) + 1);
        }
        break;
      }
    }
  }
  const queue = [...indegree.keys()].filter((ch) => indegree.get(ch) === 0);
  let order = "";
  for (let head = 0; head < queue.length; head++) {
    const ch = queue[head];
    order += ch;
    for (const after of next.get(ch)) {
      indegree.set(after, indegree.get(after) - 1);
      if (indegree.get(after) === 0) queue.push(after);
    }
  }
  return order.length === next.size ? order : "";   // letters left over sit on a cycle
}

from collections import deque

def alien_order(words):
    nxt = {ch: set() for word in words for ch in word}   # letter -> letters that come after it
    indegree = {ch: 0 for ch in nxt}                     # letter -> how many letters must come first
    for a, b in zip(words, words[1:]):
        if len(a) > len(b) and a.startswith(b):
            return ""                     # "abc" before "ab": impossible
        for x, y in zip(a, b):
            if x != y:                    # the first difference is the only clue
                if y not in nxt[x]:
                    nxt[x].add(y)         # x comes before y
                    indegree[y] += 1
                break
    queue = deque(ch for ch in nxt if indegree[ch] == 0)
    order = []
    while queue:
        ch = queue.popleft()
        order.append(ch)
        for after in nxt[ch]:
            indegree[after] -= 1
            if indegree[after] == 0:
                queue.append(after)
    return "".join(order) if len(order) == len(nxt) else ""   # letters left over sit on a cycle

String alienOrder(String[] words) {
    Map<Character, Set<Character>> next = new LinkedHashMap<>();   // letter -> letters that come after it
    Map<Character, Integer> indegree = new HashMap<>();            // letter -> how many letters must come first
    for (String word : words) {
        for (char ch : word.toCharArray()) {
            next.putIfAbsent(ch, new LinkedHashSet<>());
            indegree.putIfAbsent(ch, 0);
        }
    }
    for (int i = 0; i + 1 < words.length; i++) {
        String a = words[i], b = words[i + 1];
        if (a.length() > b.length() && a.startsWith(b)) return "";   // "abc" before "ab": impossible
        for (int j = 0; j < Math.min(a.length(), b.length()); j++) {
            char x = a.charAt(j), y = b.charAt(j);
            if (x != y) {                                // the first difference is the only clue
                if (next.get(x).add(y)) indegree.merge(y, 1, Integer::sum);   // x comes before y
                break;
            }
        }
    }
    ArrayDeque<Character> queue = new ArrayDeque<>();
    for (char ch : next.keySet()) if (indegree.get(ch) == 0) queue.add(ch);
    StringBuilder order = new StringBuilder();
    while (!queue.isEmpty()) {
        char ch = queue.poll();
        order.append(ch);
        for (char after : next.get(ch)) {
            if (indegree.merge(after, -1, Integer::sum) == 0) queue.add(after);
        }
    }
    return order.length() == next.size() ? order.toString() : "";   // letters left over sit on a cycle
}

string alienOrder(vector<string>& words) {
    map<char, set<char>> next;                           // letter -> letters that come after it
    map<char, int> indegree;                             // letter -> how many letters must come first
    for (auto& word : words) {
        for (char ch : word) {
            next[ch];                                    // creates an empty entry
            indegree[ch];
        }
    }
    for (size_t i = 0; i + 1 < words.size(); i++) {
        const string& a = words[i];
        const string& b = words[i + 1];
        if (a.size() > b.size() && a.compare(0, b.size(), b) == 0) return "";   // "abc" before "ab": impossible
        for (size_t j = 0; j < min(a.size(), b.size()); j++) {
            if (a[j] != b[j]) {                          // the first difference is the only clue
                if (next[a[j]].insert(b[j]).second) indegree[b[j]]++;   // a[j] comes before b[j]
                break;
            }
        }
    }
    queue<char> q;
    for (auto& [ch, d] : indegree) if (d == 0) q.push(ch);
    string order;
    while (!q.empty()) {
        char ch = q.front(); q.pop();
        order += ch;
        for (char after : next[ch]) {
            if (--indegree[after] == 0) q.push(after);
        }
    }
    return order.size() == next.size() ? order : "";    // letters left over sit on a cycle
}

