    if (a.length > b.length && a.startsWith(b)) return "";   // "abc" before "ab": impossible
    for (let j = 0; j < Math.min(a.length, b.length); j++) {
      if (a[j] !== b[j]) {
        next.get(a[j]).add(b[j]);             // a[j] comes before b[j]
        break;
      }
    }
  }
  const state = new Map();                    // missing = new, 1 = on the current path, 2 = done
  const finished = [];
  const visit = (ch) => {
    if (state.get(ch) === 1) return false;    // a cycle: the words contradict each other
    if (state.get(ch) === 2) return true;
    state.set(ch, 1);
    for (const after of next.get(ch)) {
      if (!visit(after)) return false;
    }
    state.set(ch, 2);
    finished.push(ch);                        // every letter after ch is already placed
    return true;
  };
  for (const ch of next.keys()) {
    if (!visit(ch)) return "";
  }
  return finished.reverse().join("");         // last to finish = first in the alphabet
}

