boolean visit(Map<Character, Set<Character>> next, Map<Character, Integer> state, StringBuilder finished, char ch) {
    int s = state.getOrDefault(ch, 0);
    if (s == 1) return false;                            // a cycle: the words contradict each other
    if (s == 2) return true;
    state.put(ch, 1);
    for (char after : next.get(ch)) {
        if (!visit(next, state, finished, after)) return false;
    }
    state.put(ch, 2);
    finished.append(ch);                                 // every letter after ch is already placed
    return true;
}

bool visit(map<char, set<char>>& next, map<char, int>& state, string& finished, char ch) {
