    if (state[ch] == 2) return true;
    state[ch] = 1;
    for (char after : next[ch]) {
        if (!visit(next, state, finished, after)) return false;
    }
    state[ch] = 2;
    finished += ch;                                      // every letter after ch is already placed
    return true;
}

